import java.io.*;
import java.math.BigInteger;
import java.util.*;

public class Main {
    public static class Task {
        int mod = 998244353;
        int add(int a, int b) {
            int c = a + b;
            if (c >= mod) return c - mod;
            if (c < 0) return  c+ mod;
            return c;
        }
        int mult(int a, int b) {
            return (int) ((long) a * b % mod);
        }
        int mult(int... x) {
            int result = 1;
            for (int val : x) {
                result = mult(result, val);
            }
            return result;
        }
        int[][] stirlingCache;
        void generateStirling() {
            stirlingCache = new int[5001][5001];
            for (int i = 0; i < stirlingCache.length; i++) {
                stirlingCache[i][0] = 0;
            }
            for (int i = 0; i < stirlingCache.length; i++) {
                stirlingCache[i][i] = 1;
            }
            for (int i = 2; i < stirlingCache.length; i++) {
                for (int j = 1; j < i; j++) {
                    stirlingCache[i][j] = add(mult(stirlingCache[i - 1][j], i - 1), stirlingCache[i - 1][j - 1]);
                }
            }
        }

        public void runAlgorithm(Scanner sc, PrintWriter pw) throws IOException {
            generateStirling();
            int n = sc.nextInt();
            int m = sc.nextInt();
            int k = sc.nextInt();
            int invM = (int)BigInteger.valueOf(m).modInverse(BigInteger.valueOf(mod)).longValue();
            int[] pValues = new int[5001];
            pValues[0] = 1;
            int currentN = n;
            int accumulatedProduct = 1;
            for (int i = 1; i <= k; i++) {
                accumulatedProduct = mult(accumulatedProduct, currentN, invM);
                currentN--;
                int total = accumulatedProduct;
                for (int j = i - 1; j >= 1; j--) {
                    int signFlag = ((i - j) % 2 == 1) ? 1 : -1;
                    total = add(total, mult(stirlingCache[i][j], add(0, signFlag * pValues[j])));
                }
                pValues[i] = total;
            }
            pw.println(pValues[k]);
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        new Task().runAlgorithm(sc, pw);
        pw.close();
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
